PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE galeri_foto (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    url TEXT NOT NULL,
    deskripsi TEXT NOT NULL,
    tanggal_upload TEXT DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "galeri_foto" ("id","url","deskripsi","tanggal_upload") VALUES(9,'data:image/jpeg;base64,','Kegiatan Program Pengenalan Studi dan Almamater (Propesa) VI STIT YA''MAL Tangerang Tahun Akademik 2025/2026','2026-06-12 16:26:07');
CREATE TABLE daftar_pengumuman (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    judul TEXT NOT NULL,
    tanggal TEXT NOT NULL,
    tipe TEXT NOT NULL
);
INSERT INTO "daftar_pengumuman" ("id","judul","tanggal","tipe") VALUES(12,'Jadwal Pengambilan Almamater di Ruang Tata Usaha','07 Juni 2026','Akademik');
CREATE TABLE daftar_unduhan (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nama TEXT NOT NULL,
    kategori TEXT NOT NULL,
    format TEXT NOT NULL,
    ukuran TEXT NOT NULL,
    download_url TEXT NOT NULL
);
INSERT INTO "daftar_unduhan" ("id","nama","kategori","format","ukuran","download_url") VALUES(9,'Surat Pemberitahuan Libur Kuliah setelah UAS Genap TA 2025/2026','Akademik','PDF','133 KB','data:application/pdf;base64,');
CREATE TABLE daftar_jurnal (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    judul TEXT NOT NULL,
    penulis TEXT NOT NULL,
    vol TEXT NOT NULL,
    status TEXT NOT NULL,
    pdf_url TEXT NOT NULL
);
